package com.company.logicdelete.starter;
import com.company.logicdelete.runtime.*;import java.io.IOException;import java.util.UUID;import javax.servlet.*;import javax.servlet.http.HttpServletRequest;
final class LogicDeleteHttpFilter implements Filter {private final RuntimeTraceProperties p;LogicDeleteHttpFilter(RuntimeTraceProperties p){this.p=p;}public void doFilter(ServletRequest req,ServletResponse res,FilterChain chain)throws IOException,ServletException{if(!(req instanceof HttpServletRequest)){chain.doFilter(req,res);return;}HttpServletRequest h=(HttpServletRequest)req;String trace=h.getHeader(p.getTraceHeader());if(trace==null||trace.trim().isEmpty())trace=UUID.randomUUID().toString().replace("-","");try{EntryContext.set("HTTP",h.getMethod()+" "+h.getRequestURI(),trace);chain.doFilter(req,res);}finally{EntryContext.clear();}}}
